ST.xhtml:p:
R_Trigger(CLK := g_bHighLowSurfaceEnableM);
R_Trigger0(CLK := g_bFlatNumEnableM);
R_Trigger1(CLK := g_bHighLowSurfaceCloseM);
R_Trigger2(CLK := g_bDiscernHeightUpLiftM);
R_Trigger3(CLK := g_bContinueCutNoUseDisSurfaceEnableM);

IF R_Trigger.Q THEN
  nHighLowSurfaceState := 1;
  g_bHighLowSurfaceEnableM := FALSE;
END_IF;

IF R_Trigger1.Q THEN
  nHighLowSurfaceState := 2;
  g_bHighLowSurfaceCloseM := FALSE;
END_IF;

IF R_Trigger2.Q THEN
  bZUpLift := TRUE;
  g_bZRelExecute := FALSE;
  g_bZRelDone := FALSE;
  g_boDiscernHeightDone := FALSE;
  g_bDiscernHeightUpLiftM := FALSE;
END_IF;

IF R_Trigger3.Q THEN
  nHighLowSurfaceState := 20;
  g_bContinueCutNoUseDisSurfaceEnableM := FALSE;
END_IF;
CASE nHighLowSurfaceState OF
  0:
  nHighLowSurfaceState := 0;
  1:
    IF R_Trigger0.Q THEN
      IF LREAL_TO_INT(g_fFlatNumM) = 1 THEN
        fZAxisHeightSurfaceA := g_fZCoordinate;
        dHeightSurFaceA := fZAxisHeightSurfaceA;
      ELSIF LREAL_TO_INT(g_fFlatNumM) = 2 THEN
        fZAxisHeightSurfaceB := g_fZCoordinate;
        dHeightSurFaceB := fZAxisHeightSurfaceB;
      END_IF;
      g_bFlatNumEnableM := FALSE;
    END_IF;

    IF g_bPlcPauseBuffer THEN
      nHighLowSurfaceState := 10;
    END_IF;
  2:
    IF fZAxisHeightSurfaceA-fZAxisHeightSurfaceB >= 0.0 THEN
      g_foHighLowIsrotate:=0.0;(*A面比B面高，不旋转*)
      g_fHighLowAngle := 90.0;
    ELSE
      g_foHighLowIsrotate:=1.0;
    END_IF;
    nHighLowSurfaceState := 0;
  10:
    IF g_bPlcStartBuffer THEN
      nHighLowSurfaceState := 1;
    END_IF;
  20:
  IF dHeightSurFaceA - dHeightSurFaceB >= 0.0 THEN
    g_foHighLowIsrotate:=0.0;(*A面比B面高，不旋转*)
    g_fHighLowAngle := 90.0;
  ELSE
    g_foHighLowIsrotate:=1.0;
  END_IF;
  nHighLowSurfaceState := 0;
END_CASE;

IF bZUpLift THEN
  dMaxHeight := SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0) - MIN(g_dSquareLenght,g_dSquareWidth)/2.0;

  IF (Axis_Z.NCTOPLC.ACTPOS + dUpLiftheight + dMaxHeight) <= g_fLiftCoord THEN
    g_fZRelDistance := dUpLiftheight + dMaxHeight;
  ELSIF (Axis_Z.NCTOPLC.ACTPOS + dUpLiftheight + dMaxHeight) > g_fLiftCoord AND (Axis_Z.NCTOPLC.ACTPOS + dMaxHeight) < g_fLiftCoord THEN
    g_fZRelDistance := g_fLiftCoord - Axis_Z.NCTOPLC.ACTPOS;
  ELSIF (Axis_Z.NCTOPLC.ACTPOS + dMaxHeight) >= g_fLiftCoord THEN
    g_fZRelDistance := dMaxHeight;
  END_IF;
  g_fZRelVelocity := dLiftVelocity;
  g_bZRelExecute := TRUE;

  IF g_bZRelDone THEN
    g_bZRelExecute := FALSE;
    g_boDiscernHeightDone := TRUE;
    M.ENABLE[221] := 0;
    bZUpLift := FALSE;
  END_IF;
END_IF;

IF g_bPlcResetBuffer THEN
  nHighLowSurfaceState := 0;
  fZAxisHeightSurfaceA :=0.0;
  fZAxisHeightSurfaceB :=0.0;
  g_foHighLowIsrotate:=0.0;
  g_fHighLowAngle := 0.0;
  g_boDiscernHeightDone := FALSE;
  bZUpLift := FALSE;
END_IF;
